DROP PROCEDURE IF EXISTS `Accounts_ForLimitation`;
DELIMITER //
CREATE PROCEDURE `Accounts_ForLimitation`(IN `p_BranchID` INT)
BEGIN
SELECT

        a.AccCode,
        a.AccName
FROM
        AccountsTb AS a
WHERE
        ((((a.AccDmType = 1

        AND a.AccFinal = 1
        AND a.Accline = 3 ))
        AND a.BranchID = p_BranchID)  OR a.AccCode=2010201)
        AND a.AccParent<>20401
        AND a.AccActive = 1;
END //
