DROP PROCEDURE IF EXISTS `Accounts_ForLimitationBASEDONAccParent`;
DELIMITER //
CREATE PROCEDURE `Accounts_ForLimitationBASEDONAccParent`(IN `p_BranchID` INT, IN `p_AccParent` BIGINT)
BEGIN
DECLARE v_IsMain INT;
SELECT cb.IsMain INTO v_IsMain FROM CoBranch cb WHERE cb.ID=p_BranchID;
SELECT
        a.AccID,
        CASE WHEN a.AccParent=2010201 THEN b.BName ELSE a.AccName END AS AccName ,
        a.CanDebit,
        a.IsLimited,
        a.LimitedVal
FROM
        AccountsTb AS a
        LEFT JOIN
        CoBranch b
        ON a.BranchID=b.ID
  WHERE
          (a.AccParent =  p_AccParent
          AND A.accActive = 1
          AND a.BranchID = p_BranchID
          AND (a.CanDebit=1 OR a.AccDmType=0 ))
OR (a.AccParent=2010201 AND p_AccParent=2010201 AND b.IsActive=1 AND v_IsMain=1 )
AND a.AccActive=1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Accounts_LimitedUpdate`;
DELIMITER //
CREATE PROCEDURE `Accounts_LimitedUpdate`(IN `p_AccID` BIGINT, IN `p_LimitationVal` DECIMAL(18,3), IN `p_IsUpdate` INT)
BEGIN
IF p_IsUpdate = 0
     THEN
          UPDATE
                  AccountsTb
          SET
                  IsLimited = 1, LimitedVal = p_LimitationVal, LimitedDate = NOW()
          WHERE
            AccID = p_AccID;
    END IF;
  IF p_IsUpdate = 1
     THEN
          UPDATE
                  AccountsTb
          SET
                  IsLimited = 0, LimitedVal = 0.000, LimitedDate = NOW()
          WHERE
            AccID = p_AccID;
    END IF;
  IF p_IsUpdate = 2
     THEN
          UPDATE
                  AccountsTb
          SET
                  LimitedVal = p_LimitationVal, LimitedDate = NOW()
          WHERE
            AccID = p_AccID;
    END IF;
END //
DELIMITER ;

