DROP PROCEDURE IF EXISTS `ACCOUNTSTB_select_Total`;
DELIMITER //
CREATE PROCEDURE `ACCOUNTSTB_select_Total`(IN `p_dat1` DATE, IN `p_date2` DATE)
BEGIN
DECLARE v_AccTotalCridet FLOAT DEFAULT 0;
DECLARE v_AccTotaldebit FLOAT DEFAULT 0;
DECLARE v_sumTotaldebit FLOAT;
DECLARE v_sumTotalcridet FLOAT;
SELECT IFNULL( SUM( a.Debit ), 0 ) INTO v_sumTotaldebit FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE IsActive=1
	  AND InsertDate BETWEEN p_dat1 AND p_date2;
SELECT IFNULL( SUM( a.Credit ), 0 ) INTO v_sumTotalcridet FROM ExSyAccounts_AccSafeActivityTb AS a
WHERE IsActive=1
	  AND InsertDate BETWEEN p_dat1 AND p_date2;
SET v_sumTotalcridet=v_sumTotalcridet+v_AccTotalCridet;
SET v_sumTotaldebit=v_sumTotaldebit+v_AccTotaldebit;
SELECT v_AccTotalCridet AS SUMtotalladdcrdt,
	   v_AccTotaldebit AS sumtotalladddebit,
	   v_sumTotaldebit AS SUMtotalDebit,
	   v_sumTotalcridet AS SUMcredit;
END //
DELIMITER ;

