DROP PROCEDURE IF EXISTS `AccSafeActivityTb_Statment`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTb_Statment`(IN `p_ISID` LONGTEXT, IN `p_D1` DATE, IN `p_D2` DATE, IN `p_ShearchType` TINYINT(1), IN `p_BaseType` INT)
BEGIN





    IF p_BaseType = 0
     THEN

        IF p_ShearchType = 1
         THEN
            SELECT
                a.ID, a.ISID, a.InsertDate,
                a.Credit, a.Debit,
                a.SafeIDMovement, a.MovementType,
                a.TypeID, a.OperationTypeID,
                a.Note,
                b.AccName AS AccFrom,
                a.AccIDFrom,
                a.AccIDTo,
                c.AccName AS AccTo,
                b.AccCode,
                a.AccBranchID,
                d.BName,
                a.CurrencyID,
                a.IsActive,
                a.DailyClosed,
                a.IsBank
            FROM ExSyAccounts_AccSafeActivityTb a
            LEFT JOIN AccountsTb b ON a.AccIDFrom = b.AccID
            LEFT JOIN AccountsTb c ON a.AccIDTo = c.AccID
            LEFT JOIN CoBranch d ON a.AccBranchID = d.ID
            WHERE a.IsActive = 1
            AND a.ISID = p_ISID;
         ELSE
            SELECT
                a.ID, a.ISID, a.InsertDate,
                a.Credit, a.Debit,
                a.SafeIDMovement, a.MovementType,
                a.TypeID, a.OperationTypeID,
                a.Note,
                b.AccName AS AccFrom,
                a.AccIDFrom,
                a.AccIDTo,
                c.AccName AS AccTo,
                b.AccCode,
                a.AccBranchID,
                d.BName,
                a.CurrencyID,
                a.IsActive,
                a.DailyClosed,
                a.IsBank
            FROM ExSyAccounts_AccSafeActivityTb a
            LEFT JOIN AccountsTb b ON a.AccIDFrom = b.AccID
            LEFT JOIN AccountsTb c ON a.AccIDTo = c.AccID
            LEFT JOIN CoBranch d ON a.AccBranchID = d.ID
            WHERE a.IsActive = 1
            AND a.InsertDate >= p_D1
            AND a.InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY);
        END IF;

     ELSE

        IF p_ShearchType = 1
         THEN
            SELECT
                a.ID, a.ISID, a.InsertDate,
                a.Credit, a.Debit,
                a.SafeIDMovement, a.MovementType,
                a.TypeID, a.OperationTypeID,
                a.Note,
                b.AccName AS AccFrom,
                a.AccIDFrom,
                a.AccIDTo,
                c.AccName AS AccTo,
                b.AccCode,
                a.AccBranchID,
                d.BName,
                a.CurrencyID,
                a.IsActive,
                a.DailyClosed
            FROM ExSyAccountsCurrency_AccSafeActivityTb a
            LEFT JOIN AccountsTb b ON a.AccIDFrom = b.AccID
            LEFT JOIN AccountsTb c ON a.AccIDTo = c.AccID
            LEFT JOIN CoBranch d ON a.AccBranchID = d.ID
            WHERE a.IsActive = 1
            AND a.ISID = p_ISID;
         ELSE
            SELECT
                a.ID, a.ISID, a.InsertDate,
                a.Credit, a.Debit,
                a.SafeIDMovement, a.MovementType,
                a.TypeID, a.OperationTypeID,
                a.Note,
                b.AccName AS AccFrom,
                a.AccIDFrom,
                a.AccIDTo,
                c.AccName AS AccTo,
                b.AccCode,
                a.AccBranchID,
                d.BName,
                a.CurrencyID,
                a.IsActive,
                a.DailyClosed
            FROM ExSyAccountsCurrency_AccSafeActivityTb a
            LEFT JOIN AccountsTb b ON a.AccIDFrom = b.AccID
            LEFT JOIN AccountsTb c ON a.AccIDTo = c.AccID
            LEFT JOIN CoBranch d ON a.AccBranchID = d.ID
            WHERE a.IsActive = 1
            AND a.InsertDate >= p_D1
            AND a.InsertDate < DATE_ADD(p_D2, INTERVAL 1 DAY);
        END IF;

    END IF;

END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `AccSafeActivityTbPOC_TOTETDATE`;
DELIMITER //
CREATE PROCEDURE `AccSafeActivityTbPOC_TOTETDATE`(IN `p_AccIDFrom` BIGINT, IN `p_DT1` DATE, IN `p_CurrencyFrom` INT, IN `p_ExistVal` TINYINT(1))
BEGIN
DECLARE v_ACCType INT;



	IF p_ExistVal = 1
		 THEN
			SELECT AccDmType INTO v_ACCType FROM
					AccountsTb AS a
			WHERE
					a.AccID = p_AccIDFrom
					AND AccActive = 1;

			SELECT
					CASE 							WHEN v_ACCType = 0 								THEN 								AccSafeActivityTb_TOTETDATE(p_AccIDFrom, p_DT1, v_ACCType, p_CurrencyFrom) 							ELSE 							0.00 					END																					   AS debit,
					CASE 							WHEN v_ACCType = 1 								THEN 								AccSafeActivityTb_TOTETDATE(p_AccIDFrom, p_DT1, v_ACCType, p_CurrencyFrom) 							ELSE 							0.00 					END																					   AS CREDET,
					AccSafeActivityTb_TOTETDATE(p_AccIDFrom, p_DT1, v_ACCType, p_CurrencyFrom) AS totel;
		END IF;

	IF p_ExistVal = 0
		 THEN
			SELECT AccDmType INTO v_ACCType FROM
					AccountsTb AS a
			WHERE
					a.AccID = p_AccIDFrom
					AND AccActive = 1;
			SELECT
					''																					   AS SN,
					'رصيد سابق'																			   AS Code,
					''																					   AS BName,
					CASE 							WHEN v_ACCType = 0 								THEN 								AccSafeActivityTb_TOTETDATE(p_AccIDFrom, p_DT1, v_ACCType, p_CurrencyFrom) 							ELSE 							0.00 					END																					   AS debit,
					CASE 							WHEN v_ACCType = 1 								THEN 								AccSafeActivityTb_TOTETDATE(p_AccIDFrom, p_DT1, v_ACCType, p_CurrencyFrom) 							ELSE 							0.00 					END																					   AS CREDET,
					AccSafeActivityTb_TOTETDATE(p_AccIDFrom, p_DT1, v_ACCType, p_CurrencyFrom) AS totel,
					''																					   AS safID,
					p_DT1																				   AS insertdate;
		END IF;
END //
DELIMITER ;

