DROP PROCEDURE IF EXISTS `ASSOCIATIONID_send_Frowtwsap_NETtotal`;
DELIMITER //
CREATE PROCEDURE `ASSOCIATIONID_send_Frowtwsap_NETtotal`(IN `p_ASSOCIATIONID` INT, IN `p_ID` INT)
BEGIN


        SELECT
            SUM(a.Credit - a.Debit) AS NET_TOTal,
            b.MEMBERNAME,
            b.phone
        FROM ExSyAccounts_AccSafeActivityTb AS a
        INNER JOIN ASSOCIATIONTB AS b ON a.AccIDFrom = b.AccID
        WHERE b.ASSOCIATIONID = p_ASSOCIATIONID
          AND (p_ID = 0 OR b.ID = p_ID)
        GROUP BY b.MEMBERNAME, b.phone;


END //
DELIMITER ;

