DROP PROCEDURE IF EXISTS `BBranchTb_BalncesStatment`;
DELIMITER //
CREATE PROCEDURE `BBranchTb_BalncesStatment`()
BEGIN
SELECT
c.BankName,
        b.BranchName,
        IFNULL(SUM(a.Debit) - SUM(a.Credit), 0) AS NetTotal
FROM
        ExSyAccounts_AccSafeActivityTb a
    LEFT JOIN
      BBranchTb b
        ON a.AccIDFrom = b.AccID
        LEFT JOIN
        BanksTb c
        ON b.BankID=c.ID
WHERE b.BranchName IS NOT NULL
GROUP BY
        b.BranchName,
        c.BankName
        ORDER BY
        c.BankName;
END //
DELIMITER ;

