DROP PROCEDURE IF EXISTS `BrancHActivity_MainBShowSafeByEmp`;
DELIMITER //
CREATE PROCEDURE `BrancHActivity_MainBShowSafeByEmp`(IN `p_InsertDate` DATE, IN `p_SecondDate` DATE, IN `p_BranchID` INT)
BEGIN
SELECT
			ROW_NUMBER() OVER (ORDER BY ISID ASC) AS '#',
			c.OperationType						  AS 'نوع العملية',
			ISID								  AS 'الرمز',
			a.INSERTDATE						  AS 'التاريخ',
			Debit								  AS 'وارد',
			Credit								  AS 'صادر'
	FROM
			AccBranchActivityTb AS a
		INNER JOIN
			CoBranch AS b
				ON a.BranchID = b.ID
		INNER JOIN
			OperationTypeTb c
				ON a.OperationTypeID = c.ID
	WHERE
			a.TypeID = 1
			AND a.INSERTDATE >= p_InsertDate
			AND a.INSERTDATE <= p_SecondDate
			AND IsClosed = 0
			AND BranchID = p_BranchID
			AND a.IsCanceled = 0;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BrancHActivity_ShowAllSafe`;
DELIMITER //
CREATE PROCEDURE `BrancHActivity_ShowAllSafe`(IN `p_InsertDate` DATE, IN `p_SecondDate` DATE)
BEGIN
SELECT
			a.BranchID AS DBRID,
			b.BName	   AS 'اسم الفرع',
			CASE 					WHEN SUM(a.Debit) > SUM(a.Credit) 						THEN 						SUM(a.Debit) - SUM(a.Credit) 					ELSE 					0 			END		   AS 'مدين',
			CASE 					WHEN SUM(a.Credit) > SUM(a.Debit) 						THEN 						SUM(a.Credit) - SUM(a.Debit) 					ELSE 					0 			END		   AS 'دائن'
	FROM
			AccBranchActivityTb a
		INNER JOIN
			CoBranch AS b
				ON a.BranchID = b.ID
	WHERE
			a.BranchID <> 1
			AND a.IsActive = 1
			AND a.TypeID = 1
			AND a.InsertDate >= p_InsertDate
			AND a.InsertDate <= p_SecondDate
			AND IsClosed = 0
			AND IsCanceled = 0
	GROUP BY
			a.BranchID,
			b.BName;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BrancHActivity_ShowSafe`;
DELIMITER //
CREATE PROCEDURE `BrancHActivity_ShowSafe`(IN `p_BrnachID` INT, IN `p_InsertDate` DATE, IN `p_SecondDate` DATE)
BEGIN
DECLARE v_BranchTotal DECIMAL(12, 3);


	SELECT SUM(a.RBVal) INTO v_BranchTotal FROM
			BenefitDistribution AS a
		INNER JOIN
			CoBranch AS c
				ON a.RBID = c.ID
		INNER JOIN
			CoBranch AS d
				ON a.DBBID = d.ID
	WHERE
			a.IsActive = 1
			AND a.ISIDType = 1
			AND a.InsertDate >= p_InsertDate
			AND a.InsertDate <= p_SecondDate
			AND RBID = p_BrnachID;
	SELECT
			a.ISID	 AS 'الرمز',
			Debit	 AS 'مدين',
			a.Credit AS 'دائن',
			e.Notes	 AS 'ملاحظات'
	FROM
			AccBranchActivityTb AS a
		INNER JOIN
			CoBranch AS c
				ON a.BranchID = c.ID
		INNER JOIN
			InternalEx AS e
				ON a.ISID = e.Code
	WHERE
			a.IsActive = 1
			AND a.TypeID = 1
			AND a.InsertDate >= p_InsertDate
			AND a.InsertDate <= p_SecondDate
			AND BranchID = p_BrnachID
			AND a.IsCanceled = 0
			AND e.IsCanceled = 0;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `BrancHActivity_ShowSafeByEmp`;
DELIMITER //
CREATE PROCEDURE `BrancHActivity_ShowSafeByEmp`(IN `p_InsertDate` DATE, IN `p_SecondDate` DATE, IN `p_BranchID` INT)
BEGIN
SELECT
			ROW_NUMBER() OVER (ORDER BY ISID ASC) AS '#',
			c.OperationType						  AS 'نوع العملية',
			ISID								  AS 'الرمز',
			a.InsertDate						  AS 'التاريخ',
			Debit								  AS 'مدين',
			Credit								  AS 'دائن'
	FROM
			AccBranchActivityTb AS a
		INNER JOIN
			CoBranch AS b
				ON a.BranchID = b.ID
		INNER JOIN
			OperationTypeTb c
				ON a.OperationTypeID = c.ID
	WHERE
			a.TypeID = 1
			AND a.InsertDate >= p_InsertDate
			AND a.InsertDate <= p_SecondDate
			AND IsClosed = 0
			AND BranchID = p_BranchID
			AND a.IsCanceled = 0;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Budget_per_mini_iliali_FILLALL`;
DELIMITER //
CREATE PROCEDURE `Budget_per_mini_iliali_FILLALL`(IN `p_BranchID` INT)
BEGIN
DROP TEMPORARY TABLE IF EXISTS tmp_TIMPP;
CREATE TEMPORARY TABLE tmp_TIMPP (BName  LONGTEXT ,Debit  DECIMAL(18,3) , Credit   DECIMAL(18,3)  ,BranchID INT   );

INSERT INTO tmp_TIMPP

select b.BName , CASE when z.AccDmType = 0  then IFNULL(SUM(Z.TenTotel),  0 )ELSE 0.0   END  as Debit ,
CASE when z.AccDmType = 1  then IFNULL(SUM(Z.TenTotel),  0 ) ELSE 0.0    END  as Credit
,Z.BranchID
from (

select * from (

SELECT a.AccName ,   SUM(b.Debit) -SUM(b.Credit ) as TenTotel , a.AccID  ,a.BranchID ,a.AccDmType from `AccountsTb`  as a
inner join  ExSyAccounts_AccSafeActivityTb as b on b.AccIDFrom = a.AccID
WHERE a.AccParent = '1010101'
and b.IsActive = 1
group by AccName ,a.AccID ,a.BranchID,a.AccDmType
UNION

SELECT b.AccName ,    SUM(d.Debit) -SUM(d.Credit )  , b.AccID ,b.BranchID ,b.AccDmType   from   `AccountsTb` as  A
INNER JOIN `AccountsTb` AS B ON A.AccCode = B.AccParent
INNER JOIN `AccountsTb` AS C ON B.AccCode = C.AccParent
inner join  ExSyAccounts_AccSafeActivityTb as d on d.AccIDFrom = c.AccID
WHERE  A.AccCode = '10104'
group by  b.AccName  , b.AccID ,b.BranchID ,b.AccDmType

 ) as x

 group by x.AccName , x.TenTotel ,x.AccID,x.BranchID,x.AccDmType
 UNION

SELECT a.AccName ,   SUM(b.Credit )  -SUM(b.Debit)  as TenTotel , a.AccID  ,a.BranchID ,a.AccDmType from `AccountsTb`  as a
inner join  ExSyAccounts_AccSafeActivityTb as b on b.AccIDFrom = a.AccID
WHERE a.AccParent = '2010601'
and b.IsActive = 1  and a.BranchID <> 1
group by AccName ,a.AccID ,a.BranchID,a.AccDmType
union

SELECT a.AccName ,   SUM(b.Credit )  -SUM(b.Debit)  as TenTotel , a.AccID  ,a.BranchID ,a.AccDmType from `AccountsTb`  as a
inner join  ExSyAccounts_AccSafeActivityTb as b on b.AccIDFrom = a.AccID
WHERE a.AccParent = '2010605'   and a.BranchID <> 1
and b.IsActive = 1
group by AccName ,a.AccID ,a.BranchID,a.AccDmType
UNION

SELECT b.AccName ,  SUM(d.Credit ) - SUM(d.Debit)  , b.AccID ,b.BranchID ,C.AccDmType   from   `AccountsTb` as  A
INNER JOIN `AccountsTb` AS B ON A.AccCode = B.AccParent
INNER JOIN `AccountsTb` AS C ON B.AccCode = C.AccParent
inner join  ExSyAccounts_AccSafeActivityTb as d on d.AccIDFrom = c.AccID
WHERE  A.AccCode = '20103'  and b.BranchID <> 1
group by  b.AccName  , b.AccID ,b.BranchID ,b.AccDmType ,C.AccDmType
UNION

SELECT b.AccName ,  SUM(d.Credit ) - SUM(d.Debit)  , b.AccID ,b.BranchID ,b.AccDmType   from   `AccountsTb` as  A
INNER JOIN `AccountsTb` AS B ON A.AccCode = B.AccParent
INNER JOIN `AccountsTb` AS C ON B.AccCode = C.AccParent
inner join  ExSyAccounts_AccSafeActivityTb as d on d.AccIDFrom = c.AccID
WHERE  A.AccCode = '20105'  and b.BranchID <> 1
group by  b.AccName  , b.AccID ,b.BranchID ,b.AccDmType

UNION


SELECT b.AccName ,  SUM(d.Credit ) - SUM(d.Debit)  , b.AccID ,b.BranchID ,b.AccDmType   from   `AccountsTb` as  A
INNER JOIN `AccountsTb` AS B ON A.AccCode = B.AccParent
INNER JOIN `AccountsTb` AS C ON B.AccCode = C.AccParent
inner join  ExSyAccounts_AccSafeActivityTb as d on d.AccIDFrom = c.AccID
WHERE  A.AccCode = '201010'  and b.BranchID <> 1
group by  b.AccName  , b.AccID ,b.BranchID ,b.AccDmType


union
SELECT b.AccName ,  SUM(d.Credit ) - SUM(d.Debit)  , b.AccID ,b.BranchID ,b.AccDmType   from   `AccountsTb` as  A
INNER JOIN `AccountsTb` AS B ON A.AccCode = B.AccParent
INNER JOIN `AccountsTb` AS C ON B.AccCode = C.AccParent
inner join  ExSyAccounts_AccSafeActivityTb as d on d.AccIDFrom = c.AccID
WHERE  A.AccCode = '20401' AND B.AccCode <> '2040102' and c.AccCode <> '204010302'  and b.BranchID <> 1  and b.BranchID = 2
group by  b.BranchID ,b.AccDmType  , b.AccName   , b.AccID ,b.BranchID ,b.AccDmType
 ) AS Z
 inner join CoBranch as b on z.BranchID = b.ID
 WHERE Z.BranchID = p_BranchID  OR p_BranchID = 0
 GROUP BY BName  ,Z.BranchID  , z.AccDmType

 ORDER BY Z.BranchID ASC;




SELECT A.BName , 	FORMAT(SUM(A.Debit ), 3)	 AS Debit  ,	FORMAT(SUM(A.Credit), 3) AS  Credit
, 	FORMAT(SUM(A.Debit )   - SUM(A.Credit), 3) AS netfortotAL , A.BranchID FROM  tmp_TIMPP  AS A
GROUP BY BName , BranchID


union
SELECT'المجموع النهائي', 	FORMAT(SUM(A.Debit ), 3)	 AS Debit  ,	FORMAT(SUM(A.Credit), 3) AS  Credit
, 	FORMAT(SUM(A.Debit )   - SUM(A.Credit), 3) AS netfortotAL ,0 FROM  tmp_TIMPP  AS A

order by  BranchID   DESC;
END //
DELIMITER ;

