DROP PROCEDURE IF EXISTS `CoBranch_GetMainBrShare`;
DELIMITER //
CREATE PROCEDURE `CoBranch_GetMainBrShare`(IN `p_RBranchID` INT, IN `p_DBranchID` INT, IN `p_InputVal` DECIMAL(12,3))
BEGIN
DECLARE v_RBrType INT;
DECLARE v_DBrType INT;
DECLARE v_CulRes DECIMAL(12, 3);
DECLARE v_RestShare DECIMAL(12, 3);
DECLARE v_BrRt DECIMAL(12, 3);
DECLARE v_RBShare DECIMAL(12, 3);
DECLARE v_DBShare DECIMAL(12, 3);
DECLARE v_DbrRt DECIMAL(12, 3);
DECLARE v_AgentRestVal DECIMAL(12, 3);
DECLARE v_MainBr INT;


	SELECT ID INTO v_MainBr FROM
			CoBranch
	WHERE
			IsMain = 1;
	SET v_RBrType = (SELECT BranchType FROM CoBranch WHERE ID = p_RBranchID);
	SET v_DBrType = (SELECT BranchType FROM CoBranch WHERE ID = p_DBranchID);
	IF v_DBrType = 1
		AND
		v_RBrType = 1
		 THEN

			IF p_RBranchID = v_MainBr
				 THEN
					SELECT MainBranchBenefit INTO v_DbrRt FROM
							CoBranch
					WHERE
							ID = p_DBranchID;
SET v_DBShare = p_InputVal * v_DbrRt / 100;
SET v_RBShare = p_InputVal - v_DBShare;
				END IF;
		END IF;
	SELECT
			v_DBShare AS DBShare,
			v_RBShare AS RBShare;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CoBranch_LoadBranchRate`;
DELIMITER //
CREATE PROCEDURE `CoBranch_LoadBranchRate`(IN `p_BranchID` INT)
BEGIN


		SELECT
				`ID`,
				`BName`,
				BranchRate,
				MainBranchBenefit,
