DROP PROCEDURE IF EXISTS `cobrnch_lode_For_Setting_roles`;
DELIMITER //
CREATE PROCEDURE `cobrnch_lode_For_Setting_roles`(IN `p_FrmScreensTb_ID` INT, IN `p_UeserID` INT, IN `p_ColmenValue` INT)
BEGIN
DECLARE v_AccfillValue_select int;

SELECT AccfillValue INTO v_AccfillValue_select FROM  `FrmScreensTb_selectITimsFormMovent_UeserID`  as a
inner join `FrmScreensTb_selectITimsFormMovent` as b on b.Id = a.ColmenValue
where
a.FrmScreensTb_ID = p_FrmScreensTb_ID and a.UeserID = p_UeserID     and b.ColmenValue = p_ColmenValue;



 if p_ColmenValue =1
  THEN
if v_AccfillValue_select <> 0
 THEN

SELECT b.ID , b.BName ,a.FrmScreensTb_ID

  FROM `FrmScreensTb_selectITimsFormMovent_UeserID` as a
  inner join CoBranch as b on a.AccfillValue = b.ID
  inner join FrmScreensTb_selectITimsFormMovent as c on a.ColmenValue = c.Id
  where   a.FrmScreensTb_ID    = p_FrmScreensTb_ID
  and a.UeserID = p_UeserID  and c.ColmenValue = p_ColmenValue;

  END IF;

  if v_AccfillValue_select = 0
 THEN
select
	   ID,
	   BName
From   CoBranch AS A  WHERE IsActive = 1 AND  A.BranchType = 1;

  END IF;

  END IF;


  if p_ColmenValue = 2
   THEN
  select  a.ColmenValue  from
  `FrmScreensTb_selectITimsFormMovent_UeserID`  as a
inner join `FrmScreensTb_selectITimsFormMovent` as b on b.Id = a.ColmenValue
where
a.FrmScreensTb_ID = p_FrmScreensTb_ID and a.UeserID = p_UeserID     and b.ColmenValue = p_ColmenValue;
  END IF;
END //
DELIMITER ;

