DROP PROCEDURE IF EXISTS `CurrencymovementCust_FILLGRid`;
DELIMITER //
CREATE PROCEDURE `CurrencymovementCust_FILLGRid`(IN `p_TYPE` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT)
BEGIN
IF p_TYPE=0
 THEN
SELECT
        a.Code AS ISID,
        a.InsertDate AS Inseart_Date,
        p_dt1 AS D1,
        p_dt2 AS D2,
        b.CurCode AS ACCFRom,
        a.CusName ,
        a.CustIDNo,
       CASE WHEN a.TypeOP=24 THEN a.BPrice1 ELSE '0.000' END CRedetTO,

       CASE WHEN a.TypeOP=24 THEN a.Purchasingprice ELSE '0.000' END buyprice,
       CASE WHEN a.TypeOP=24 THEN a.BPrice2 ELSE '0.000' END CRedetDL,
       CASE WHEN a.TypeOP=25 THEN a.BPrice1 ELSE '0.000' END ACC_DEPET_TO,
       CASE WHEN a.TypeOP=25 THEN a.Purchasingprice ELSE '0.000' END salesPurchaseprice,
       CASE WHEN a.TypeOP=25 THEN a.BPrice2 ELSE '0.000' END Revenue,
       CASE WHEN a.TypeOP=25 THEN 'بيع' ELSE 'شراء' END TYPEFROM,
       CASE WHEN a.thepurpose=0 THEN 'سياحة' WHEN a.thepurpose=1 THEN 'علاج' WHEN a.thepurpose=2 THEN 'دراسة' END thepurpose
FROM
        CurrenciesBuyandsellTB a
        LEFT JOIN
        CurrencyMainTb b
        ON a.FirstCurrency=b.ID
        where
        					a.`IsActive` = 1
					AND a.InsertDate BETWEEN p_dt1 AND p_dt2
          AND a.TypeOP=24
          AND (a.FirstCurrency=p_ACCFRom OR p_ACCFRom=0);
   END IF;

IF p_TYPE=1
 THEN
SELECT
        a.Code AS ISID,
        a.InsertDate AS Inseart_Date,
         b.CurCode AS ACCFRom,
        a.CusName ,
        a.CustIDNo,
       CASE WHEN a.TypeOP=24 THEN a.BPrice1 ELSE '0.000' END CRedetTO,
       CASE WHEN a.TypeOP=24 THEN a.Purchasingprice ELSE '0.000' END buyprice,
       CASE WHEN a.TypeOP=24 THEN a.BPrice2 ELSE '0.000' END CRedetDL,
       CASE WHEN a.TypeOP=25 THEN a.BPrice1 ELSE '0.000' END ACC_DEPET_TO,
       CASE WHEN a.TypeOP=25 THEN a.Purchasingprice ELSE '0.000' END salesPurchaseprice,
       CASE WHEN a.TypeOP=25 THEN a.BPrice2 ELSE '0.000' END Revenue,
       CASE WHEN a.TypeOP=25 THEN 'بيع' ELSE 'شراء' END TYPEFROM,
       CASE WHEN a.thepurpose=0 THEN 'سياحة' WHEN a.thepurpose=1 THEN 'علاج' WHEN a.thepurpose=2 THEN 'دراسة' END thepurpose
FROM
        CurrenciesBuyandsellTB a
                LEFT JOIN
        CurrencyMainTb b
        ON a.FirstCurrency=b.ID
        where
        					a.`IsActive` = 1
					AND a.InsertDate BETWEEN p_dt1 AND p_dt2
          AND a.TypeOP=25
          AND (a.FirstCurrency=p_ACCFRom OR p_ACCFRom=0);
   END IF;

IF p_TYPE=2
 THEN
SELECT
        a.Code AS ISID,
        a.InsertDate AS Inseart_Date,
        b.CurCode AS ACCFRom,
        a.CusName ,
        a.CustIDNo,
       CASE WHEN a.TypeOP=24 THEN a.BPrice1 ELSE '0.000' END CRedetTO,
       CASE WHEN a.TypeOP=24 THEN a.Purchasingprice ELSE '0.000' END buyprice,
       CASE WHEN a.TypeOP=24 THEN a.BPrice2 ELSE '0.000' END CRedetDL,
       CASE WHEN a.TypeOP=25 THEN a.BPrice1 ELSE '0.000' END ACC_DEPET_TO,
       CASE WHEN a.TypeOP=25 THEN a.Purchasingprice ELSE '0.000' END salesPurchaseprice,
       CASE WHEN a.TypeOP=25 THEN a.BPrice2 ELSE '0.000' END Revenue,
       CASE WHEN a.TypeOP=25 THEN 'بيع' ELSE 'شراء' END TYPEFROM,
       CASE WHEN a.thepurpose=0 THEN 'سياحة' WHEN a.thepurpose=1 THEN 'علاج' WHEN a.thepurpose=2 THEN 'دراسة' END thepurpose
FROM
        CurrenciesBuyandsellTB a
                LEFT JOIN
        CurrencyMainTb b
        ON a.FirstCurrency=b.ID
        where
        					a.`IsActive` = 1
					AND a.InsertDate BETWEEN p_dt1 AND p_dt2
          AND (a.FirstCurrency=p_ACCFRom OR p_ACCFRom=0);
   END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencymovementCust_SalelimtedStatment`;
DELIMITER //
CREATE PROCEDURE `CurrencymovementCust_SalelimtedStatment`(IN `p_AccID` VARCHAR(50), IN `p_CurrID` INT)
BEGIN
DECLARE v_MAxVal DECIMAL(15,3);
DECLARE v_LeftVal DECIMAL(15,3);




SELECT Max(a.MaxVal) INTO v_MAxVal FROM CurrLimetedTB a WHERE a.CurID=p_CurrID;

SELECT v_MAxVal-IFNULL(Sum(a.BPrice1),0.000) INTO v_LeftVal FROM
        CurrenciesBuyandsellTB a
        where
        					a.`IsActive` = 1

          AND a.TypeOP=25
          AND a.FirstCurrency=p_CurrID
          AND a.CustIDNo=p_AccID;

SELECT
        a.Code AS ISID,
        a.InsertDate AS Inseart_Date,
         b.CurCode AS ACCFRom,
        a.CusName ,
        a.CustIDNo,
        b.CuName,
       CASE WHEN a.TypeOP=25 THEN a.BPrice1 ELSE '0.000' END ACC_DEPET_TO,
       CASE WHEN a.TypeOP=25 THEN a.Purchasingprice ELSE '0.000' END salesPurchaseprice,
       CASE WHEN a.TypeOP=25 THEN a.BPrice2 ELSE '0.000' END Revenue,
       CASE WHEN a.TypeOP=25 THEN 'بيع' ELSE 'شراء' END TYPEFROM,
       CASE WHEN a.thepurpose=0 THEN 'سياحة' WHEN a.thepurpose=1 THEN 'علاج' WHEN a.thepurpose=2 THEN 'دراسة' END thepurpose,
       IFNULL(CAST(v_MAxVal AS CHAR),'غير محدد') AS MaxVal,
       IFNULL(CAST(v_LeftVal AS CHAR),'مفتوح') AS LeftVal
FROM
        CurrenciesBuyandsellTB a
                LEFT JOIN
        CurrencyMainTb b
        ON a.FirstCurrency=b.ID
        where
        					a.`IsActive` = 1

          AND a.TypeOP=25
          AND a.FirstCurrency=p_CurrID
          AND a.CustIDNo=p_AccID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencymovementPruse_FILLGRid2`;
DELIMITER //
CREATE PROCEDURE `CurrencymovementPruse_FILLGRid2`(IN `p_Bid` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT)
BEGIN
SELECT
			ROW_NUMBER() OVER (
			ORDER BY a.ID ASC)															 AS SN,
			a.ID,
			a.`ISID`,
			b.CurCode																	 AS ACCFRom,
			c.CuName																	 AS ACCCRint0,
			FORMAT(a.`CRedetTO`, 3)											 AS CRedetTO,
			FORMAT(a.`Purchaseprice`, 3)									 AS Purchaseprice,
			CASE 					WHEN a.Typeofsalebuyorsell = 3 						THEN 						FORMAT(CRedetTO * salesPurchaseprice, 3) 					ELSE 					FORMAT(a.`CRedetDL`, 3) 			END																			 AS CRedetDL,
			FORMAT(a.`ACC_DEPET_DL`, 3)										 AS ACC_DEPET_DL,
			FORMAT(a.ACC_DEPET_TO, 3)										 AS ACC_DEPET_TO,
			CASE 					WHEN a.Typeofsalebuyorsell = 3 						THEN 						CRedetDL 					ELSE 					NetSale + ACC_DEPET_DL 			END																			 AS Revenue,
			UName,
			`Inseart_Date`,
			a.`IsActive`,
			FORMAT(a.NetSale, 3)											 AS NetSale,
			FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal,
			CASE 					WHEN a.Typeofsalebuyorsell = 0 						THEN 						FORMAT(a.`Purchaseprice`, 3) 					WHEN a.Typeofsalebuyorsell = 2 						AND ACC_DEPET_TO <> 0 						THEN 						FORMAT((NetSale + ACC_DEPET_DL) / ACC_DEPET_TO, 3) 					ELSE 					'0.000' 			END																			 AS buyprice,
			CASE 					WHEN a.Typeofsalebuyorsell = 1 						OR a.Typeofsalebuyorsell = 3 						THEN 						FORMAT(a.`Purchaseprice`, 3) 					ELSE 					'0.000' 			END																			 AS saleprice,
			CASE 					WHEN a.Typeofsalebuyorsell = 2 						THEN 						FORMAT(a.`Purchaseprice`, 3) 					ELSE 					IFNULL(salesPurchaseprice, 0.000) 			END																			 AS salesPurchaseprice,
			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي'  					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف'  			END																			 AS TYPEFROM
	FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a

		INNER JOIN
			CurrencyMainTb AS b
				ON a.`ACCFRom` = b.ID
		INNER JOIN
			CurrencyMainTb AS c
				ON a.`ACCCRint0` = c.ID
		INNER JOIN
			TB_Users AS d
				ON a.UESER_INSERt = d.USID
		INNER JOIN
			NewCurrencyPriceOwnDetailsTb AS e
				ON a.ACCFRom = e.CurrencyIDTo

	WHERE
			a.`IsActive` = 1
			AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
			AND (   a.ACCFRom = p_ACCFRom
					OR p_ACCFRom = 0)
			AND a.BID = p_Bid
	ORDER BY
			a.ID ASC;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencymovementPruse_FILLGRid3`;
DELIMITER //
CREATE PROCEDURE `CurrencymovementPruse_FILLGRid3`(IN `p_Bid` INT, IN `p_dt1` DATE, IN `p_dt2` DATE, IN `p_ACCFRom` INT)
BEGIN
SELECT
			ROW_NUMBER() OVER (
			ORDER BY a.ID ASC)															 AS SN,
			a.ID,
			a.`ISID`,
			b.CurCode																	 AS ACCFRom,
			c.CuName																	 AS ACCCRint0,
			FORMAT(a.`Purchaseprice`, 3)									 AS Purchaseprice,
			FORMAT(`SafeIDCur_GetNetTotal`(a.BID, a.ACCFRom, a.ID), 3) AS GetAccVal,
			UName,
			`Inseart_Date`,
			a.`IsActive`,
			FORMAT(a.`CRedetTO`, 3)											 AS CRedetTO
			,
			FORMAT(a.ACC_DEPET_TO, 3)										 AS ACC_DEPET_TO
			,
			CASE 					WHEN a.Typeofsalebuyorsell = 0 						OR a.Typeofsalebuyorsell = 3 						THEN 						a.`CRedetTO` 					WHEN a.Typeofsalebuyorsell = 1 						OR a.Typeofsalebuyorsell = 2 						THEN 						a.ACC_DEPET_TO * -1 			END																			 AS Currencyquantity

			,
			CASE 					WHEN a.Typeofsalebuyorsell = 0 						THEN 						FORMAT(a.`Purchaseprice`, 3) 					WHEN a.Typeofsalebuyorsell = 3 						THEN 						salesPurchaseprice 			END																			 AS buyprice

			,
			CASE 					WHEN a.Typeofsalebuyorsell = 3 						THEN 						FORMAT(CRedetTO * salesPurchaseprice, 3) 					ELSE 					FORMAT(a.`CRedetDL`, 3) 			END																			 AS CRedetDL

			,
			CASE 					WHEN a.Typeofsalebuyorsell = 2 						THEN 						FORMAT(a.`Purchaseprice`, 3) 					WHEN a.Typeofsalebuyorsell = 1 						THEN 						IFNULL(salesPurchaseprice, 0.000) 			END																			 AS salesPurchaseprice

			,
			CASE 					WHEN a.Typeofsalebuyorsell = 3 						THEN 						a.`ACC_DEPET_DL` 					ELSE 					NetSale + ACC_DEPET_DL 			END																			 AS ACC_DEPET_DL
			,
			CASE 					WHEN a.Typeofsalebuyorsell = 3 						THEN 						a.`CRedetDL` 					ELSE 					a.`ACC_DEPET_DL` 			END																			 AS Revenue
			,
			FORMAT(a.NetSale, 3)											 AS NetSale
			,
			CASE 					WHEN a.Typeofsalebuyorsell = 1 						OR a.Typeofsalebuyorsell = 3 						THEN 						FORMAT(a.`Purchaseprice`, 3) 					WHEN a.Typeofsalebuyorsell = 2 						THEN 						FORMAT(a.`Purchaseprice`, 3) 			END																			 AS saleprice
			,
			Case when TypeofCalcORsaleBuy=1 			Then 			CASE 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء نقدي' 					WHEN `TYPEFROM` = 0 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع نقدي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء خارجي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع خارجي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء خارجي' 					WHEN `TYPEFROM` = 1 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع خارجي'            WHEN `TYPEFROM` = 2 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء ت.خارجي' 					WHEN `TYPEFROM` = 2 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع ت.خارجي' 					WHEN `TYPEFROM` = 2 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء ت.خارجي' 					WHEN `TYPEFROM` = 2 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع ت.خارجي' 					WHEN `TYPEFROM` = 3 						AND a.Typeofsalebuyorsell = 0 						THEN 						'شراء عالمصرف' 					WHEN `TYPEFROM` = 3 						AND a.Typeofsalebuyorsell = 1 						THEN 						'بيع عالمصرف' 					WHEN `TYPEFROM` = 3 						AND a.Typeofsalebuyorsell = 2 						THEN 						'إسترجاع شراء عالمصرف' 					WHEN `TYPEFROM` = 3 						AND a.Typeofsalebuyorsell = 3 						THEN 						'إسترجاع بيع عالمصرف' 			END	Else CASE 					WHEN  						 a.Typeofsalebuyorsell = 1 						THEN 						'عجز خزنة' 					WHEN  						 a.Typeofsalebuyorsell = 0 THEN 						'فائض خزنة'	END	END																 AS TYPEFROM
	FROM
			ExSyAccountsCurrency_CurrencymovementPruse AS a
		INNER JOIN
			CurrencyMainTb AS b
				ON a.`ACCFRom` = b.ID
		INNER JOIN
			CurrencyMainTb AS c
				ON a.`ACCCRint0` = c.ID
		INNER JOIN
			TB_Users AS d
				ON a.UESER_INSERt = d.USID

	WHERE
			a.`IsActive` = 1
			AND `Inseart_Date` BETWEEN p_dt1 AND p_dt2
			AND (   a.ACCFRom = p_ACCFRom
					OR p_ACCFRom = 0)
			AND a.BID = p_Bid
      AND a.TYPEFROM=0
	ORDER BY
			a.ID ASC;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyPric_LoadToUpdate`;
DELIMITER //
CREATE PROCEDURE `CurrencyPric_LoadToUpdate`(IN `p_ID` INT, IN `p_PriceType` INT, IN `p_TypeID` INT)
BEGIN
IF p_TypeID = 1
     THEN
          SELECT
                  a.ID,
                  b.CuName,
                  b.CuName AS CurrencyIDFrom,
                  c.CuName AS CurrencyIDTo,
                  a.`BuyPrice`,
                  a.`SalePrice`
          FROM
                  `NewCurrencyPriceOwnDetailsTb` AS a
              INNER JOIN
                CurrencyMainTb AS b
                  ON a.CurrencyIDFrom = b.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON a.CurrencyIDTo = c.ID
              INNER JOIN
                NewCurrencyPricesOwnTb AS d
                  ON a.CPID = d.ID
          WHERE
                  a.ID = p_ID
                  AND d.PriceType = p_PriceType;
    END IF;
  IF p_TypeID = 2
     THEN
          SELECT
                  a.ID,
                  b.CuName,
                  b.CuName AS CurrencyIDFrom,
                  c.CuName AS CurrencyIDTo,
                  a.`BuyPrice`,
                  a.`SalePrice`
          FROM
                  `NewCurrencyPriceOwnDetailsTb` AS a
              INNER JOIN
                CurrencyMainTb AS b
                  ON a.CurrencyIDFrom = b.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON a.CurrencyIDTo = c.ID
              INNER JOIN
                NewCurrencyPricesOwnTb AS d
                  ON a.CPID = d.ID
          WHERE
                  a.ID = p_ID
                  AND d.PriceType = p_PriceType;
    END IF;
     IF p_TypeID = 3
     THEN
          SELECT
                  a.ID,
                  b.CuName,
                  b.CuName AS CurrencyIDFrom,
                  c.CuName AS CurrencyIDTo,
                  a.`BuyPrice`,
                  a.`SalePrice`
          FROM
                  `NewCurrencyPriceOwnDetailsTb` AS a
              INNER JOIN
                CurrencyMainTb AS b
                  ON a.CurrencyIDFrom = b.ID
              INNER JOIN
                CurrencyMainTb AS c
                  ON a.CurrencyIDTo = c.ID
              INNER JOIN
                NewCurrencyPricesOwnTb AS d
                  ON a.CPID = d.ID
          WHERE
                  a.ID = p_ID
                  AND d.PriceType = p_PriceType;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `CurrencyPricCatogre`;
DELIMITER //
CREATE PROCEDURE `CurrencyPricCatogre`(IN `p_ID` INT, IN `p_Tipe` INT, IN `p_TypeID` INT)
BEGIN
IF p_TypeID = 1
 THEN
	IF p_Tipe = 1
		 THEN

			SELECT
					a.id,
					b.CuName,
					b.CuName AS CurrencyIDFrom,
					c.CuName AS CurrencyIDTo,
					0		 AS Typesf,
					''		 AS BankName,
					a.`BuyPrice`,
					a.`SalePrice`
			FROM
					`CurrencyPriceDetailsTb` AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyIDFrom = b.id
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyIDTo = c.id
			WHERE
					a.id = p_ID;

		END IF;
	IF p_Tipe = 2
		 THEN

			SELECT
					a.id,
					b.CuName,
					b.CuName AS CurrencyIDFrom,
					c.CuName AS CurrencyIDTo,
					1		 AS Typesf,
					d.BankName,
					a.`BuyPrice`,
					a.`SalePrice`
			FROM
					CurrencyPriceDetailsBancksTb AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyIDFrom = b.id
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyIDTo = c.id
				INNER JOIN
					BanksTb AS d
						ON a.Banck_ID = d.id
			WHERE
					a.id = p_ID;

		END IF;
		END IF;
IF p_TypeID = 2
 THEN
	IF p_Tipe = 1
		 THEN

			SELECT
					a.id,
					b.CuName,
					b.CuName AS CurrencyIDFrom,
					c.CuName AS CurrencyIDTo,
					0		 AS Typesf,
					''		 AS BankName,
					a.`BuyPrice`,
					a.`SalePrice`
			FROM
					`CurrencyPriceOwnDetailsTb` AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyIDFrom = b.id
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyIDTo = c.id
			WHERE
					a.id = p_ID;

		END IF;
	IF p_Tipe = 2
		 THEN

			SELECT
					a.id,
					b.CuName,
					b.CuName AS CurrencyIDFrom,
					c.CuName AS CurrencyIDTo,
					1		 AS Typesf,
					d.BankName,
					a.`BuyPrice`,
					a.`SalePrice`
			FROM
					CurrencyPriceDetailsBancksTb AS a
				INNER JOIN
					CurrencyMainTb AS b
						ON a.CurrencyIDFrom = b.id
				INNER JOIN
					CurrencyMainTb AS c
						ON a.CurrencyIDTo = c.id
				INNER JOIN
					BanksTb AS d
						ON a.Banck_ID = d.id
			WHERE
					a.id = p_ID;

		END IF;
		END IF;
END //
DELIMITER ;

