DROP PROCEDURE IF EXISTS `EmpActivity_ShowSafeByEmp`;
DELIMITER //
CREATE PROCEDURE `EmpActivity_ShowSafeByEmp`(IN `p_InsertDate` DATE, IN `p_SecondDate` DATE, IN `p_BranchID` INT, IN `p_SafeID` INT)
BEGIN
SELECT
			*
	FROM
			(
select ROW_NUMBER() OVER (ORDER BY ISID ASC) AS '#',a.ISID as 'الرمز', c.OperationType as 'نوع العملية',  a.InsertDate as 'التاريخ',Debit as 'إيرادات',Credit as 'مصروفات'
 from AccEmpActivityTb as a inner join CoBranch as b on a.AccBranchID=b.ID inner join OperationTypeTb c on a.OperationTypeID=c.ID  where a.TypeID=1 And a.InsertDate >=(p_InsertDate) and a.InsertDate<=(p_SecondDate) and a.AccBranchID=(p_BranchID) and a.SafeID=(p_SafeID) and a.OperationTypeID <> 6
 ) AS tvf_EmActivity_ShowSafeByEmp;
END //
DELIMITER ;

