DROP PROCEDURE IF EXISTS `EMPLOYEETB_SearchByID`;
DELIMITER //
CREATE PROCEDURE `EMPLOYEETB_SearchByID`(IN `p_ID` INT)
BEGIN
SELECT
          a.ID,
          a.Code,
          EMPNAME,
          NATNUMBER,
          CLASSIFICATION,
          Phone1,
          Phone2,
          BIRTHDATE,
          EMPDATE,
          PassportNo,
          Nationality,
          CertificateType,
          SalaryVal,
          EMail,
		IFNULL(a.CanDebit,'') as  CanDebit ,
			IFNULL(a.Jobgrade,'') as Jobgrade  ,
          a.IsActive,
          a.BranchID,
          a.BankID,
          a.BankNo,
          a.AccOwner,
          a.BBranchID,
    CAST(a.BankSalaryCalc AS SIGNED) AS BankSalaryCalc
  FROM
          EmployeeTb AS a
  WHERE
          a.ID = p_ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPLOYEETB_UpdateById`;
DELIMITER //
CREATE PROCEDURE `EMPLOYEETB_UpdateById`(IN `p_ID` INT, IN `p_CODE` LONGTEXT, IN `p_EMPNAME` LONGTEXT, IN `p_NATNUMBER` LONGTEXT, IN `p_CLASSIFICATION` INT, IN `p_PHONE1` VARCHAR(50), IN `p_PHONE2` VARCHAR(50), IN `p_BIRTHDATE` DATE, IN `p_EMPDATE` DATE, IN `p_PassportNo` LONGTEXT, IN `p_Nationality` LONGTEXT, IN `p_CertificateType` LONGTEXT, IN `p_SalaryVal` DOUBLE, IN `p_EMail` LONGTEXT, IN `p_Debit` DOUBLE, IN `p_Credit` DOUBLE, IN `p_ISACTIVE` TINYINT(1), IN `p_BranchID` INT)
BEGIN
UPDATE
			EmployeeTb
	SET
			Code = p_CODE, EMPNAME = p_EMPNAME, NATNUMBER = p_NATNUMBER,
			`CLASSIFICATION` = p_CLASSIFICATION,
			Phone1 = p_PHONE1,
			Phone2 = p_PHONE2,
			BIRTHDATE = p_BIRTHDATE,
			EMPDATE = p_EMPDATE,
			PassportNo = p_PassportNo,
			Nationality = p_Nationality,
			CertificateType = p_CertificateType,
			SalaryVal = p_SalaryVal,
			EMail = p_EMail,
			Debit = p_Debit,
			Credit = p_Credit,
			IsActive = p_ISACTIVE,
			BranchID = p_BranchID
	WHERE
		ID = p_ID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `EMPLOYEETB_UpdateByIdSalary`;
