DROP PROCEDURE IF EXISTS `FrmScreensTb_Details_UESIRID_get`;
DELIMITER //
CREATE PROCEDURE `FrmScreensTb_Details_UESIRID_get`(IN `p_UeserID` INT, IN `p_ColmenValue` INT)
BEGIN
select a.ScreenID ,CAST(a.Can_branch AS SIGNED) as
Can_branch , Can_safID , a.Can_Close_safid ,CaN_calCylaTion ,Can_CarunCe
,a.Can_Accfrom , a.Can_accTo ,Can_ISbacnk  ,b.ScreenName  ,a.can_Acount , a.can_cash , a.can_banck ,d.GroupNAme  ,e.MainName
from `FrmScreensTb_Details_UESIRID` as a
inner join `FrmScreensTb2` as b on a.ScreenID = b .ScreenID
inner join  `Group-main` as d on b.GRoup_ID= d.id
inner join FrmMainTb as e on b.MainScreenID = e.MainID
inner join FrmScreensTb_selectITimsFormMovent as c on a.ScreenID = c.FrmScreensTb_ID
where a.UeserID = p_UeserID and ColmenValue = p_ColmenValue
order by b.MainScreenID , a.ScreenID asc;
END //
DELIMITER ;

