DROP PROCEDURE IF EXISTS `FrmScreensTb_selectITimsFormMovent_UeserID_fill_dvg`;
DELIMITER //
CREATE PROCEDURE `FrmScreensTb_selectITimsFormMovent_UeserID_fill_dvg`(IN `p_UeserID` INT)
BEGIN
select a.Id , b.ScreenName , c.ColmensName ,d.BName    from FrmScreensTb_selectITimsFormMovent_UeserID as
a
inner join FrmScreensTb2 as b on a.FrmScreensTb_ID = b.ScreenID
inner join FrmScreensTb_selectITimsFormMovent as c on a.ColmenValue = c.Id
inner join CoBranch as d on a.AccfillValue =  d.ID
where a.UeserID = p_UeserID and c.ColmenValue = 1

union
select a.Id , b.ScreenName , c.ColmensName ,'كل الفروع والخزائن '  from FrmScreensTb_selectITimsFormMovent_UeserID as
a
inner join FrmScreensTb2 as b on a.FrmScreensTb_ID = b.ScreenID
inner join FrmScreensTb_selectITimsFormMovent as c on a.ColmenValue = c.Id
where a.UeserID = 21  and AccfillValue = 0   and c.ColmenValue = 1
union
select a.Id , b.ScreenName , c.ColmensName ,c.ColmensName   from FrmScreensTb_selectITimsFormMovent_UeserID as
a
inner join FrmScreensTb2 as b on a.FrmScreensTb_ID = b.ScreenID
inner join FrmScreensTb_selectITimsFormMovent as c on a.ColmenValue = c.Id
where a.UeserID = p_UeserID      and c.ColmenValue <>  1;
END //
DELIMITER ;

