DROP PROCEDURE IF EXISTS `FrmViewBranchSafeDetails`;
DELIMITER //
CREATE PROCEDURE `FrmViewBranchSafeDetails`(IN `p_InsertDate` DATE, IN `p_SecondDate` DATE, IN `p_BranchID` INT)
BEGIN
SELECT
          b.AccName,
          COUNT(id) AS count
  FROM
          ExSyAccounts_AccSafeActivityTb a
      LEFT JOIN
        AccountsTb b
          ON a.AccIDFrom = b.AccID
  WHERE
          b.AccParent LIKE '101040%'
          AND a.InsertDate BETWEEN p_InsertDate AND p_SecondDate
          AND (b.BranchID = p_BranchID OR p_BranchID=0)
          AND a.IsActive=1
          AND b.AccActive=1
  GROUP BY
          b.AccName

  ORDER BY
          COUNT(id) DESC;
END //
DELIMITER ;

