DROP PROCEDURE IF EXISTS `GET_colmens_InternalEx`;
DELIMITER //
CREATE PROCEDURE `GET_colmens_InternalEx`(IN `p_code` LONGTEXT)
BEGIN
Select a.`Code` ,`SenderName` ,`SPhone1` ,`RecievedName` , `RPhone1` ,`OverallVal`
,`BranchRecievedID`
, `BranchDeliveredID` , cb.BName AS BRName,BrShare,
c.CityName,BrShare,BdShare,DATE_FORMAT(ConfirmCanceledDate, '%Y-%m-%d') AS ConfirmCanceledDate,DATE_FORMAT(a.ConfirmCanceledDate, '%h:%i') AS ConfirmCanceledTime,
case when a.BranchDeliveredID  <> 0   then (select c.`BName` from  CoBranch  as  c  where c.id = a.BranchDeliveredID ) else 'لايوجد وكيل'  END  as BName


,
c.CityName


  from `InternalEx` as a


  LEFT join `CitiesTb` as c on  a.`DeliveryPlace` = c.id
  LEFT JOIN CoBranch cb ON a.BranchRecievedID=cb.ID
   where a.Code = p_code;
END //
DELIMITER ;

