DROP PROCEDURE IF EXISTS `GET_PHONE_SaenFroWtsaap`;
DELIMITER //
CREATE PROCEDURE `GET_PHONE_SaenFroWtsaap`(IN `p_AccID` INT)
BEGIN
SELECT
          x.PHONE1,
          x.code
  FROM
          (

              SELECT
                      b.PHONE1,
                      a.AccID,
                      b.code

              FROM
                      `AccountsTb` AS
                      a
                  INNER JOIN
                    `EmployeeTb`
                    AS b
                        ON a.accid = b.accid
              UNION
              SELECT
                    case when a.sand_Group_ID = 0   then  b.PHONE1  else a.Group_ID_fro_watssap  END as  PHONE1 ,
                      a.AccID,
                      b.code  AS code

              FROM
                      `AccountsTb` AS
                      a
                  INNER JOIN
                    `CustomersTb`
                    AS b
                        ON a.accid = b.accid

              UNION
              SELECT
                      b.PHONE1 ,
                      a.AccID,
                      b.code

              FROM
                      `AccountsTb` AS
                      a
                  INNER JOIN
                    `CreditAccountsTb`
                    AS b
                        ON a.accid = b.accid


              UNION
              SELECT
                     c.IDGroup ,
                      a.AccID,
                      b.code

              FROM
                      `AccountsTb` AS
                      a
                  INNER JOIN
                    `CoBranch`
                    AS b
                        ON a.accid = b.CurrentAccID
inner join whtsappGRoup as c on b.ID = c.Branchid
              UNION
              SELECT
                      a.AccPhone ,
                      a.AccID,
                      CAST(a.AccCode AS CHAR)
              FROM
                      AccountsTb a
              WHERE

                      a.AccParent LIKE '201010%'
                      AND a.Accline = 4

             UNION
              SELECT
                      a.AccPhone ,
                      a.AccID,
                      CAST(a.AccCode AS CHAR)
              FROM
                      AccountsTb a
              WHERE

                      a.AccParent LIKE '2010180%'
                      AND a.Accline = 4


             UNION
              SELECT
                      a.AccPhone ,
                      a.AccID,
                      CAST(a.AccCode AS CHAR)
              FROM
                      AccountsTb a
              WHERE

                      a.AccParent LIKE '204010%'
                      AND a.Accline = 4

                        UNION
                          SELECT
                      b.PHONE  ,
                      a.AccID,
                      a.AccCode
              FROM
                      `AccountsTb` AS
                      a
                  INNER JOIN
                   ASSOCIATIONTB
                    AS b
                        ON a.accid = b.accid
                        ) AS x
  WHERE
          x.AccID = p_AccID;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `GET_Power_of_Currency_byCurrName`;
