DROP PROCEDURE IF EXISTS `InternalEx_SearchForCurrentRecorde`;
DELIMITER //
CREATE PROCEDURE `InternalEx_SearchForCurrentRecorde`(IN `p_Code` LONGTEXT)
BEGIN
SELECT
          A.Code,
          A.InsertDate,
          A.SenderName,
          A.SPhone1,
          A.SPhone2,

          A.SenderIDNo,
          A.RecievedName,
          A.RPhone1,
          A.RPhone2,

          A.RecievedIDNo,
          A.RecievedCurrencyID,
          A.DeliveredCurrencyID,
          A.OverallVal,
          A.ExVal,
          A.SafeRecievedID,
          A.SafeDeliveredID,
          A.DeliveryPlace,
          A.BranchRecievedID,
          A.BranchDeliveredID,
          A.ConfirmType,
          Notes AS Notes,
          A.IsAccFrom,
          A.AccFrom,
          A.IsAccTo,
          A.AccTo,
          A.BBranchAccID,
          A.BBRANCHID,
          A.EXTRVAL,
          i.SName,
          A.ServiceType,
          a.Type_Moble,
         CONCAT('تنفيذ الموظف: ', tu.UName) AS RUName,
         CASE WHEN A.ConfirmType=2 OR A.ConfirmType=6 THEN CONCAT('سلمت بواسطة: ', t.UName) ELSE '' END AS DUName

  FROM
          InternalEx AS A
          LEFT JOIN
          InternalEx_Stautes i
          ON A.ConfirmType = i.ConfirmType
          LEFT JOIN
          TB_Users tu
          ON a.SafeRecievedID=tu.USID
                    LEFT JOIN
          TB_Users t
          ON a.SafeDeliveredID=t.USID
  WHERE
          A.Code = p_Code
          AND A.IsActive = 1;
END //
DELIMITER ;

