DROP PROCEDURE IF EXISTS `New_CurrenciesBuyandsellTB_SelectAll`;
DELIMITER //
CREATE PROCEDURE `New_CurrenciesBuyandsellTB_SelectAll`(IN `p_UserInsert` INT)
BEGIN
SELECT
			a.Code			  AS 'الرمز',
			a.InsertDate	  AS 'التاريخ',
			CASE 					WHEN a.IsCachorBank = 0 						THEN 						'بيع داخلي'            WHEN a.IsCachorBank = 1 THEN            'بيع خارجي' 					 WHEN a.IsCachorBank = 3 THEN 					'بيع مصرفي' 			END				  AS 'نوع السداد',
			e.AccName		  AS 'من حساب'

			,
			c.CuName		  AS 'ع/المشتراه',
			a.BPrice1		  AS 'القيمة',
			d.CuName		  AS 'ع/المصروفة',
			a.Purchasingprice AS 'التكلفة',
			a.BPrice2		  AS ' المصروفة',
			f.AccName		  AS 'لحساب'

	 FROM
			CurrenciesBuyandsellTB AS a
		LEFT JOIN
			CoBranch AS b
				ON a.BranchID = b.ID
		LEFT JOIN
			CurrencyMainTb AS c
				ON a.FirstCurrency = c.ID
		LEFT JOIN
			CurrencyMainTb AS d
				ON a.CurrencyTo = d.ID
		LEFT JOIN
			AccountsTb AS e
				ON a.SaFACCount = e.AccID
		LEFT JOIN
			AccountsTb AS f
				ON a.AccSafeTo = f.AccID
	WHERE
			a.IsActive = 1
			AND a.TypeOP = 24
			AND a.UeserInset=p_UserInsert;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `New_CurrenciesBuyandsellTB_SelectAll2`;
DELIMITER //
CREATE PROCEDURE `New_CurrenciesBuyandsellTB_SelectAll2`(IN `p_UserInsert` INT)
BEGIN
SELECT
			a.Code			  AS 'الرمز'

			,
			a.InsertDate	  AS 'التاريخ',
			CASE 					WHEN a.IsCachorBank = 0 						THEN 						'بيع داخلي'            WHEN a.IsCachorBank = 1 THEN            'بيع خارجي' 					 WHEN a.IsCachorBank = 3 THEN 					'بيع مصرفي' 			END				  AS 'نوع السداد',
			f.AccName		  AS 'من حساب',
			c.CuName		  AS 'ع/المباعة',
			a.BPrice1		  AS 'ق/المباعة',
			d.CuName		  AS 'ع/المستلمه',
			a.Purchasingprice AS 'التكلفة',
			a.BPrice2		  AS ' ق/المستلمه',
			e.AccName		  AS 'لحساب'

	FROM
			CurrenciesBuyandsellTB AS a
		LEFT JOIN
			CoBranch AS b
				ON a.BranchID = b.ID
		LEFT JOIN
			CurrencyMainTb AS c
				ON a.FirstCurrency = c.ID
		LEFT JOIN
			CurrencyMainTb AS d
				ON a.CurrencyTo = d.ID
		LEFT JOIN
			AccountsTb AS e
				ON a.SaFACCount = e.AccID
		LEFT JOIN
			AccountsTb AS f
				ON a.AccSafeTo = f.AccID
	WHERE
			a.IsActive = 1
			AND a.TypeOP = 25
			AND a.UeserInset=p_UserInsert;
END //
DELIMITER ;

