DROP PROCEDURE IF EXISTS `Request_to_summon_driversTB_SELECT`;
DELIMITER //
CREATE PROCEDURE `Request_to_summon_driversTB_SELECT`(IN `p_BranchID` INT, IN `p_LastUpdate` DATETIME)
BEGIN


    SELECT
        A.ID,
        B.BName,
        C.UName,
        A.insertDate,
        A.`Time`,
        CASE              WHEN A.IsAccpit = 0 THEN 'تحت الطلب'             WHEN A.IsAccpit = 1 THEN 'تمت الموافقة'             WHEN A.IsAccpit = 2 THEN 'تم تأكيد الوصول'             ELSE 'لم يتم قبول الطلب'         END AS IsAccpit,
        A.LastUpdate
    FROM Request_to_summon_driversTB AS A
    INNER JOIN CoBranch AS B ON A.BranchID = B.ID
    INNER JOIN TB_Users AS C ON A.UeserID_insert = C.USID
    WHERE A.BranchID = p_BranchID
      AND A.LastUpdate > p_LastUpdate
    ORDER BY A.LastUpdate ASC;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `Request_to_summon_driversTB_SELECT_Updated`;
DELIMITER //
CREATE PROCEDURE `Request_to_summon_driversTB_SELECT_Updated`(IN `p_BranchID` INT, IN `p_LastUpdate` DATETIME)
BEGIN


    SELECT
        A.ID,
        B.BName,
        C.UName,
        A.insertDate,
        A.`Time`,
        CASE              WHEN A.IsAccpit = 0 THEN 'تحت الطلب'             WHEN A.IsAccpit = 1 THEN 'تمت الموافقة'             WHEN A.IsAccpit = 2 THEN 'تم تأكيد الوصول'             ELSE 'لم يتم قبول الطلب'         END AS IsAccpit,
        A.LastUpdate
    FROM Request_to_summon_driversTB AS A
    INNER JOIN CoBranch AS B ON A.BranchID = B.ID
    INNER JOIN TB_Users AS C ON A.UeserID_insert = C.USID
    WHERE A.BranchID = p_BranchID
      AND (A.LastUpdate IS NOT NULL AND A.LastUpdate > p_LastUpdate)
    ORDER BY A.LastUpdate ASC;
END //
DELIMITER ;

