DROP PROCEDURE IF EXISTS `RptGroup_print`;
DELIMITER //
CREATE PROCEDURE `RptGroup_print`(IN `p_ProfID` INT)
BEGIN
select b.ProfileName ,
 e.MainName,
 f.ScreenName ,a.CanEdit ,a.CanDelete,a.CanPrint,a.CanSearch
from  UserAccessProfileTemplate as a inner join `ProfileName` as b  on a.ProfileID = b.ProfID
inner join  `UserROOLMAINPROFILETP` as c on a.ProfileID= c.profid and a.MainID= c.mainid
inner join FrmScreensTb2 as d on a.ScreenID = d.ScreenID
inner join `FrmMainTb` as e on e.MainID =c.mainid
inner join Ueser_Group_main as g on a.Group_ID = g.GrouID and  a.ProfileID= g.`Profile`
inner join FrmScreensTb2 as f on a.ScreenID = f.ScreenID
where a.ProfileID = p_ProfID and a.CanShow = 1 and c.canshow = 1 and g.Canshow= 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `RptUserAccessProfileTemplate_ueserId`;
DELIMITER //
CREATE PROCEDURE `RptUserAccessProfileTemplate_ueserId`(IN `p_USID` INT)
BEGIN
select
a.UName , f.ProfileName  ,e.ScreenName ,  d.MainName ,
b.CanSave ,b.CanEdit ,b.CanDelete , b.CanSearch , b.CanPrint
,g.BName
from TB_Users as a
inner join UserAccessProfileTemplate_ID as b on a.USID = b.UserID
inner join UserROOLMAINPROFILETP_ID as c on a.USID = c.Userid and b.MainID= c.mainid
inner join FrmScreensTb2  as e on b.ScreenID = e.ScreenID
inner join FrmMainTb as d on e.MainScreenID= d.MainID
inner join ProfileName as f on a.UserType = f.ProfID
inner join CoBranch as g on a.BranchID = g.ID
inner join Ueser_Group_main_ID as h on a.USID = h.UserID and b.Group_ID= h.GrouID
where a.IsActive =1 and b.CanShow =1  and a.USID = p_USID  and  h.Canshow = 1 and c.canshow = 1

order by  d.MainID ,e.ScreenID  asc;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `SafeBranch_ExProfitsDist`;
DELIMITER //
CREATE PROCEDURE `SafeBranch_ExProfitsDist`(IN `p_BrnachID` INT, IN `p_InsertDate` DATE, IN `p_SecondDate` DATE)
BEGIN
DECLARE v_BranchTotal DECIMAL(12, 3);


	SELECT SUM(a.RBVal) INTO v_BranchTotal FROM
			BenefitDistribution AS a
		INNER JOIN
			CoBranch AS c
				ON a.RBID = c.ID
		INNER JOIN
			CoBranch AS d
				ON a.DBBID = d.ID
	WHERE
			a.IsActive = 1
			AND a.ISIDType = 1
			AND a.InsertDate >= p_InsertDate
			AND a.InsertDate <= p_SecondDate
			AND RBID = p_BrnachID;
	SELECT
			d.BName		 AS 'الفرع',
			SUM(a.DBVal) AS 'الإجمالي',
			v_BranchTotal AS BRTOTAL
	FROM
			BenefitDistribution AS a
		INNER JOIN
			CoBranch AS c
				ON a.RBID = c.ID
		INNER JOIN
			CoBranch AS d
				ON a.DBBID = d.ID
	WHERE
			a.IsActive = 1
			AND a.ISIDType = 1
			AND a.InsertDate >= p_InsertDate
			AND a.InsertDate <= p_SecondDate
			AND RBID = p_BrnachID
			AND IsCanceled = 0
	GROUP BY
			d.BName;
END //
DELIMITER ;

