DROP PROCEDURE IF EXISTS `TB_Users_LoadUSERBYBRANCH`;
DELIMITER //
CREATE PROCEDURE `TB_Users_LoadUSERBYBRANCH`(IN `p_BranchID` INT)
BEGIN
SELECT
			UName,
			USID
	FROM
			TB_Users
	WHERE
			BranchID = p_BranchID
			AND TypeID = 1
			AND TB_Users.IsActive = 1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `TB_Users_LoadUSERBYBRANCHANDALLBRANCH`;
DELIMITER //
CREATE PROCEDURE `TB_Users_LoadUSERBYBRANCHANDALLBRANCH`(IN `p_BranchID` INT)
BEGIN
IF p_BranchID <> 0
		 THEN
			SELECT
					UName,
					USID
			FROM
					TB_Users
			WHERE
					BranchID = p_BranchID
					AND TypeID = 1
					AND TB_Users.IsActive = 1;
		END IF;
	IF p_BranchID = 0
		 THEN
			SELECT
					UName,
					USID
			FROM
					TB_Users
			WHERE
					TypeID = 1
					AND TB_Users.IsActive = 1;
		END IF;
END //
DELIMITER ;

