CREATE PROCEDURE `UserAccessProfileTemplate_ueserId_roles`(IN `p_ProfileGID` INT, IN `p_USERID` INT)
BEGIN
SELECT
          a.CanShow,
          b.ShortName
  FROM
          UserAccessProfileTemplate_ID AS a
      INNER JOIN
        FrmScreensTb2 AS b
          ON a.ScreenID = b.ScreenID
  WHERE
          a.UserID = p_USERID
  UNION
  SELECT
          a.`canshow`,
          b.ShortName
  FROM
          `UserROOLMAINPROFILETP_ID` AS a

      INNER JOIN
        `FrmMainTb` AS b
          ON a.mainid = b.mainid
  WHERE
          Userid = p_USERID
  UNION
