          a.canshow,
          b.`Button name`
  FROM
          NotificationUSERID AS a
      INNER JOIN
        frmNotifications AS b
          ON a.NotificationID = b.NotificationID
  WHERE
          A.userID = p_USERID
  UNION ALL
  SELECT
          a.canshow,
          b.BUTTONNAME2
  FROM
          NotificationUSERID AS a
      INNER JOIN
        frmNotifications AS b
          ON a.NotificationID = b.NotificationID
  WHERE
          A.userID = p_USERID;
END //
