DROP PROCEDURE IF EXISTS `users_Activated_user_accounts`;
DELIMITER //
CREATE PROCEDURE `users_Activated_user_accounts`()
BEGIN
select a.Reg , a.id ,
case when a.AccountType  <>  'pos' then  IFNULL( b.AccName,a.phone) else  d.Name_post END
 as AccName  , a.phone ,c.BName ,
case when a.UeserType = 1 then 'حساب موظف' when a.UeserType = 2 then 'حساب عميل' when a.UeserType = 3 and a.AccountType = 'Main' then 'حساب وكيل' when a.UeserType = 5 then 'خزينة' when a.UeserType = 4 then 'لوحة تحكم' when a.UeserType = 6 then 'حساب زبون عادي' when a.UeserType = 7 then 'حساب مندوب' when a.UeserType = 3 and a.AccountType = 'pos' then 'حساب  نقطة وكيل' END  as UeserType
,a.device_id
,IFNULL(b.AccCode,0)  as AccCode ,
a.Count_ACtivties
from  users as a left join AccountsTb as b on
a.AccID = b.AccID
inner join CoBranch as c on a.BrancchID = c.ID
left join AuthorizedUsers as d on a.id = d.UserID
where Reg= 'Yes';
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `users_Activated_user_accounts_NO`;
DELIMITER //
CREATE PROCEDURE `users_Activated_user_accounts_NO`()
BEGIN
select a.Reg , a.id ,
case when a.AccountType  <>  'pos' then  IFNULL( b.AccName,a.phone) else  d.Name_post END
 as AccName  , a.phone ,c.BName ,
case when a.UeserType = 1 then 'حساب موظف' when a.UeserType = 2 then 'حساب عميل' when a.UeserType = 3 and a.AccountType = 'Main' then 'حساب وكيل' when a.UeserType = 5 then 'خزينة' when a.UeserType = 4 then 'لوحة تحكم' when a.UeserType = 6 then 'حساب زبون عادي' when a.UeserType = 7 then 'حساب مندوب' when a.UeserType = 3 and a.AccountType = 'pos' then 'حساب  نقطة وكيل' END  as UeserType
,a.device_id
,IFNULL(b.AccCode,0)  as AccCode ,
a.Count_ACtivties
from  users as a left join AccountsTb as b on
a.AccID = b.AccID
inner join CoBranch as c on a.BrancchID = c.ID
left join AuthorizedUsers as d on a.id = d.UserID
where Reg= 'no';
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `whatsapp_contacts`;
