DROP PROCEDURE IF EXISTS `Withdrawal_AccountTBLoadLine3ToLKP`;
DELIMITER //
CREATE PROCEDURE `Withdrawal_AccountTBLoadLine3ToLKP`(IN `p_BranchID` INT)
BEGIN
SELECT
        a.AccCode,
        a.AccName
FROM
        AccountsTb AS a

WHERE
        (a.AccDmType = 1
        AND a.AccFinal = 1
        AND a.Accline = 3
        AND a.BranchID = p_BranchID

        AND a.AccActive = 1)
OR
(a.AccCode=2010201 OR a.AccCode=4010205 OR a.AccCode=4010206 );
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `WithdrawalTb_SELECTALL`;
DELIMITER //
CREATE PROCEDURE `WithdrawalTb_SELECTALL`(IN `p_BranchID` INT)
BEGIN
		SELECT
				a.WDCode,
				a.WithdrawalDate,
				b.AccName AS firstuname,
				c.AccName AS Seconduname,
				a.WithdrawalValue,
				a.Notes,
				d.BName
		FROM
				WithdrawalTb AS a
			INNER JOIN
				AccountsTb AS b
					ON a.WithdrawalFrom = b.AccID
			INNER JOIN
				AccountsTb AS c
					ON a.WithdrawalTo = c.AccID
			INNER JOIN
				CoBranch AS d
					ON a.BranchID = d.ID
		WHERE
				a.IsActive = 1
				AND a.BranchID = p_BranchID
				AND a.typeid=14;
	END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZPRT_MultiAcountEditTB_Select`;
DELIMITER //
CREATE PROCEDURE `ZPRT_MultiAcountEditTB_Select`(IN `p_AccCode` LONGTEXT)
BEGIN
SELECT

   B.AccName ,
   a. Debit ,
   a. Credit,
   a. Notes  ,
   d.AccName AS AccName2

FROM
        MultiAcountEditDetailsTB as a
        inner join `MultiAcountEditTB` as c on A.MISID=C.Code
        inner join accountsTb as b on a.AccID=B.Accid
        INNER JOIN accountsTb as d on a.AccIDTo=d.AccID
        WHERE a.IsActive=1
        and c.Code=p_AccCode
        and c.IsActive=1;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CreditAccountStatement`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CreditAccountStatement`(IN `p_BranchID` INT, IN `p_CurrencyTo` INT)
BEGIN
DECLARE v_IsDefault INT;


  SELECT IsDefault INTO v_IsDefault FROM
          CurrencyMainTb AS CMT
  WHERE
          cmt.id = p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;
  IF v_IsDefault = 1
     THEN
      SELECT
              a.AccID,
              a.AccName                                                                        AS CustName,
              FORMAT(IFNULL(SUM(b.Debit), 0.000), 3)                               AS Debit,
              FORMAT(IFNULL(SUM(b.Credit), 0.00), 3)                               AS Credit,
              FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,

              0                                                                                AS TypeMov
      FROM
              AccountsTb  AS a
          INNER JOIN
            ExSyAccounts_AccSafeActivityTb AS b
              ON a.AccID = b.AccIDFrom
      WHERE
              (       a.BranchID = p_BranchID
                      OR p_BranchID = 0)
              AND a.AccActive = 1
              AND b.IsActive = 1
              AND a.AccParent LIKE '2010180%'
      GROUP BY

              a.AccName,
              AccID;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS `ZRPT_CustomerStatement`;
DELIMITER //
CREATE PROCEDURE `ZRPT_CustomerStatement`(IN `p_BranchID` INT, IN `p_CurrencyTo` INT, IN `p_USERID` INT)
BEGIN
DECLARE v_IsDefault BIT;
DECLARE v_CanShowHACC BIT;
	SELECT IsDefault INTO v_IsDefault FROM
			CurrencyMainTb AS CMT
			where cmt.ID= p_CurrencyTo
 ORDER BY CMT.ID DESC LIMIT 1;

SELECT t.CanShowHACC INTO v_CanShowHACC FROM TB_Users t WHERE t.USID=p_USERID
 ORDER BY t.USID DESC LIMIT 1;

	IF v_IsDefault = 1
		 THEN
					SELECT
							a.AccID,
							a.CustName,
              A.Code ,
              A.Phone1 ,
							FORMAT(IFNULL(SUM(b.Credit), 0.00) - IFNULL(SUM(b.Debit), 0.000), 3) AS ACCNETtotel,
							a.ID
					FROM
							`CustomersTb` AS a
						LEFT JOIN
							ExSyAccounts_AccSafeActivityTb AS b
								ON a.AccID = b.AccIDFrom
					WHERE
							(		a.BranchID = p_BranchID
									OR p_BranchID = 0)
							AND a.IsActive = 1
              AND (a.HiddenAccount=0 OR a.HiddenAccount=v_CanShowHACC)
					GROUP BY
							a.ID,
							a.CustName,
							a.AccID,
               A.Code,
               A.Phone1
               ORDER BY
               A.ID;

		END IF;
	IF v_IsDefault =0
   THEN

      SELECT a.AccID,
             a.CustName,
              A.Code ,
              A.Phone1 ,
             FORMAT(IFNULL(SUM(b.Debit), 0.000)-IFNULL(SUM(b.Credit), 0.00), 3)   AS ACCNETtotel,
             a.ID
        FROM `CustomersTb` AS a
        LEFT JOIN ExSyAccountsCurrency_AccSafeActivityTb AS b
          ON a.AccID = b.AccIDFrom
       WHERE (a.BranchID = p_BranchID
            OR p_BranchID = 0)
         AND a.IsActive = 1
         AND (b.CurrencyID = p_CurrencyTo OR B.CurrencyID IS NULL)
         AND (a.HiddenAccount=0 OR a.HiddenAccount=v_CanShowHACC)
      GROUP BY a.ID,
               a.CustName,
               AccID,
               A.Code,
               A.Phone1
               ORDER BY
               A.ID;
		END IF;
END //
DELIMITER ;

